"""Make a single comparable report from the two independently sealed ranker panels."""
import gzip
import json
from itertools import combinations
from pathlib import Path

ROOT=Path(__file__).resolve().parent


def load(n):return json.loads((ROOT/n).read_bytes())
def f(v,n=2):return f"{v:.{n}f}".replace(".",",")
def ci(c):
    return f"{f(100*c['mean'])} [{f(100*c['ci'][0])}; {f(100*c['ci'][1])}]"


def report():
    labels={"dense":"PU Dense-FT","hash64":"R-GCN CPU, hash64","availability":"R-GCN CPU, availability","rgcn":"Residual R-GCN, полный train"}
    panels=[m for m in labels if (ROOT/f"{m}-render-audit.json").exists()]
    doc=["# Объединение пересекающихся цитат при чтении памяти агента","",
        "Сравниваем способы потратить один и тот же бюджет после ранжирования траектории. Два соседних provenance unit (PU) могут включать один и тот же участок вывода инструмента. При обычном доборе целых блоков этот участок попадает в текст дважды. Мы сохраняем его координаты, показываем один раз и используем свободное место для других исходных фрагментов. Всем политикам предъявлены одинаковые ранги внутри каждой модели, 2 000 запросов и 1 207 траекторий официального test ISETrace. Процесс оценивает извлечённые свидетельства. Генерацию конечного ответа здесь не измеряем. [Основной протокол](PROTOCOL_RU.md) · [ISETrace](https://arxiv.org/html/2609.25913v3)","",
        "## Главное сравнение с жёсткой ценой выводимой строки","",
        "| Ранжировщик | Строгий skip, случаев FS | Объединение + добор, случаев FS | Δ FS, п.п. [95% ДИ] | Выигрыши / проигрыши | Δ Coverage, п.п. [95% ДИ] |",
        "|---|---:|---:|---:|---:|---:|"]
    for m in panels:
        strict=load(f"{m}-strict-results.json");c=strict["paired"]["F-skip"]
        doc.append(f"| {labels[m]} | {strict['stats']['skip']['fs']} | {strict['stats']['F']['fs']} | {ci(c['change']['full_support'])} | {c['win']} / {c['lose']} | {ci(c['change']['coverage'])} |")
    doc+=["","Каждая строка текста состоит из буквальных срезов источника и переносов строк между срезами. Координаты передаются отдельно. На каждом запросе для всех шести вариантов дополнительная проверка штатным BertTokenizerFast пересчитала стоимость полного текста. Максимум составил 2 048 WordPiece. Если исходным PU на границе слова присвоена меньшая цена, чем у выделенной подстроки, единое для всех методов правило укорачивает последнюю цитату до ближайшей подходящей границы. Для Dense-FT этот контроль добавлен после просмотра двух переполнений, для R-GCN зафиксирован до получения его рангов. [Протокол физического лимита](STRICT_RENDER_RU.md)","",
        "## Откуда возникает прирост","",
        "Skip идёт по рангу и добавляет целый PU, когда тот помещается. U выводит объединение исходных диапазонов skip. W дополнительно добирает целые PU по исходному рангу. F заполняет оставшееся место короткими окнами из ещё не прочитанного текста. Родителей просматриваем по рангу и берём до одного окна на родителя. При выборе окна используется число совпадающих терминов запроса. Контроли W0/F0 сохраняют физически повторяющиеся цитаты исходного skip и применяют те же правила добора остатка. [Протокол контроля остатка](OVERLAP_CONTROL_RU.md)","",
        "| Ранжировщик | Вариант | Full Support, % | Coverage, % | Density, % | Выдано WordPiece, среднее |",
        "|---|---|---:|---:|---:|---:|"]
    for m in panels:
        data=load(f"{m}-strict-results.json")["stats"]
        for arm in ["skip","U","W0","W","F0","F"]:
            d=data[arm];doc.append(f"| {labels[m]} | {arm} | {f(100*d['fs']/2000)} | {f(100*d['coverage'])} | {f(100*d['density'])} | {f(d['tokens'],1)} |")
    for m in panels:
        result=load(f"{m}-results.json");inc=result["incidence"];p=result["paired"];st=result["strata"]
        strict=load(f"{m}-strict-results.json");audit=load(f"{m}-render-audit.json");install=load(f"{m}-forecast-seal.json")
        c=strict["paired"]["F-F0"];rank=labels[m]
        doc.extend(["",f"### {rank}","",
            f"Повторяющиеся символы присутствовали в исходном skip у {inc['intrinsic_overlap']}/2 000 запросов. Только объединение освободило в среднем {f(inc['mean_true_saved'])} WordPiece исходного рендера. Квантили экономии 0/25/50/75/95/100% — {', '.join(f(x,0) for x in inc['true_saved_quantiles'])}. После обоих доборов {inc['chars_added']} запросов получили дополнительные исходные символы и {inc['event_added']} — материал из дополнительного исходного поля. В {inc['whole_added']} случаях удалось добрать целый PU, в {inc['window_added']} — хотя бы одно окно.",
            "",f"Первичный вариант до буквальной коррекции выиграл у исходного skip в {p['F-skip']['win']} случаях, проиграл в {p['F-skip']['lose']}. При наличии исходного перекрытия было {st['skip-overlap']['F-skip']['win']} выигрышей, при его отсутствии — {st['skip-nooverlap']['F-skip']['win']}. Целочисленный добор дал {p['W-skip']['win']} выигрышей, затем дробный добавил ещё {p['F-W']['win']}. В прямом сравнении двух физически строгих дробных процедур F−F0 разность FS составила {ci(c['change']['full_support'])} п.п. Все интервалы парные, 10 000 повторов по целым траекториям. [Поштучная первичная оценка]("+m+"-outcomes.json.gz) · [Поштучная строгая оценка]("+m+"-strict-outcomes.json.gz)",
            "",f"При токенизации всей исходной строки {inc['rerender_diff']} оценок отличались от суммы метаданных PU, {inc['render_overflow']} исходных строк оказались длиннее 2 048. После объединения {inc['base_infeasible']} случаев всё ещё требовали условного возврата к исходным единицам в первичном протоколе. Строгая процедура укоротила {strict['stats']['skip']['affected']} выдач skip и {strict['stats']['F']['affected']} выдач F. Изменился индикатор FS относительно первичного результата у {len(strict['stats']['skip']['fs_changed'])} и {len(strict['stats']['F']['fs_changed'])} запросов соответственно. Нарушений включения скорректированного skip в F — {strict['inclusion_violations']['skip-in-F']}. [Метрики строгого режима]("+m+"-strict-results.json)",
            "",f"Для основного упаковщика на трёх CPU-процессах потребовалось {f(install['wall_seconds'],1)} с настенных и {f(install['cpu_worker_seconds'],1)} с процессорного времени рабочих процессов, включая чтение данных. Предвычисление рангов в эту стоимость не входит. Для F независимый рендер на запрос в среднем содержит {f(audit['by_arm']['F']['bytes']/2000,1)} байта UTF-8 и {f(audit['by_arm']['F']['parts']/2000,1)} непрерывного диапазона. Контроллер физически развернул и токенизировал все {audit['literal_documents']} выдач за {f(audit['seconds'],1)} с. [Контрольная сумма корпуса выводимых строк]("+m+"-render-audit.json)"])
    if len(panels)>1:
        wins={}
        for m in panels:
            rows=json.loads(gzip.decompress((ROOT/f"{m}-strict-outcomes.json.gz").read_bytes()))
            wins[m]={r["q"] for r in rows if r["a"]["F"]["full_support"]>r["a"]["skip"]["full_support"]}
        doc+=["","### Совпадение выигрышей на общих вопросах","",
            "Ранжировщики оцениваются на одних вопросах. Всего хотя бы в одном варианте F добавил полный support на "
            +str(len(set.union(*wins.values())))+" разных запросах. "
            +" ".join(f"Пересечение выигрышных запросов {labels[a]} и {labels[b]}: {len(wins[a]&wins[b])}." for a,b in combinations(panels,2))]
    if any((ROOT/f"{m}-clean-sensitivity.json").exists() for m in panels):
        doc+=["","### Проверка после исключения повторяющихся обучающих полей","",
              "Заранее определённый в R19 фильтр удаляет 125 вопросов test, если поле с эталонной цитатой целиком совпадает с любым полем среди 3 894 обучающих запросов Dense-FT. Для R-GCN проверяется предобученный плотный компонент. Это дополнительный анализ чувствительности уже запечатанных прогнозов. Состав подгрупп взят из прежнего аудита; отдельной проверки смысловых дубликатов здесь нет. [Описание фильтра R19](../../graph_memory_round19/split_overlap/REPORT_RU.md)","",
              "| Ранжировщик | Строгие F / skip на 1 875 запросах | Δ FS, п.п. [95% ДИ] | Выигрышей в 125 исключённых |",
              "|---|---:|---:|---:|"]
        for m in panels:
            path=ROOT/f"{m}-clean-sensitivity.json"
            if path.exists():
                part=load(path.name)["partitions"];clean=part["no_train_field_match"]
                doc.append(f"| {labels[m]} | {clean['full_support_counts']['F']} / {clean['full_support_counts']['skip']} | {ci(clean['full_support'])} | {part['train_field_match']['win']} |")
    if any(m in panels for m in ("hash64","availability")):
        doc+=["","Основная резервная CPU-панель hash64 использует 101 train-запрос, панель чувствительности availability — 100. Это два сокращённых обучения графовой модели на разных выбранных траекториях. Опубликованная система использует полный train и пять seed. [Дополнение к протоколу](CPU_TRANSFER_RU.md)"]
    doc+=["","## Интерпретация и границы результата","",
        "Для каждого запроса зададим S — объединение множеств координат выданных символов по паре «событие, JSON-путь». Full Support равно единице, когда множество эталонных координат G целиком содержится в S. Поэтому включение S(skip) ⊆ S(F) обеспечивает неубывание Full Support и доли покрытых символов. Для первичного алгоритма включение проверено самостоятельно по всем координатам. При укорочении в строгом режиме его проверяем заново эмпирически. Плотность может снижаться, когда в выдачу добавляется нерелевантный текст. В нативной метрике знаменатель Density дважды учитывает дважды показанные символы; U может повысить Density при неизменном числителе.","",
        "Объединение пересекающихся интервалов давно применяется в RAG, в том числе в функции chunks_deoverlap пакета ragnar. Здесь измерены влияние повторной оплаты одних и тех же символов в агентской памяти, выгода заполнения освободившегося места и реальный размер строк после токенизации. Для доступных ранжировщиков использовался один seed на том же test, который уже анализировался в других опытах. Сравнения с пятизапусковыми средними из статьи дополнительно смешивают влияние ранжировщика и сборки контекста. Источники в статье — целые PU, в вариантах F/F0 и строгом пограничном усечении могут участвовать части PU. Тарифицировались только буквальные тексты цитат. Служебные адреса и инструкция агенту учитываются отдельно. [Документация ragnar](https://ragnar.tidyverse.org/reference/chunks_deoverlap.html) · [Авторский код GraphMemory](https://github.com/xiaoqi-7/GraphMemory/tree/df29287116fa1565b3fd6b485022cd6090dc0b27) · [Воспроизведение](REPRODUCE_RU.md)"]
    doc+=["","Работа Chroma оценивает релевантность на уровне токенов и отмечает цену повторно возвращаемых токенов при перекрытии. Более близкий по времени препринт QESChunker оптимизирует статические границы индексируемых фрагментов на размеченных или сгенерированных парах «вопрос — свидетельство» и оценивает полноту извлечения. В нашем опыте ранг и исходное разбиение фиксированы до сборки цитат. Полезная следующая проверка — сколько даёт та же сборка поверх индекса, при построении которого уже оптимизировали полное покрытие. [Chroma Technical Report](https://www.trychroma.com/research/evaluating-chunking) · [Zhao et al., QESChunker](https://arxiv.org/abs/2610.36557)"]
    (ROOT/"REPORT_RU.md").write_bytes(("\n".join(doc)+"\n").encode())


if __name__=="__main__":report()
